/* GENERATED by tools/make_c_tables.py (stage 75a, reworked 2026-11-22): where the data tables of the core are.  Do not edit.  Contains no byte of the ROM:
 * the bytes are installed at start-up from the owner's ROM (assets/rom_install.c writes the asset blob, assets_boot() calls tables_set). */
#ifndef PM_CORE_TABLES_H
#define PM_CORE_TABLES_H

#include <stddef.h>
#include <stdint.h>

#define RAM_0600_SIZE 512u   /* $0600: the tables `Start` builds in RAM from the nibble stream */
#define ROM_BA00_SIZE 1536u  /* $BA00: the ROM window the core indexes into */
#define MAZE_DATA_SIZE 920u  /* the maze `Start` expands to $0800 */

/* RAM $07AE, 24 bytes: frames per step, four-step cycles (RAM image of NibblesMoveDelay) */
extern const uint8_t *const MOVE_DELAY;
/* ROM $BDB9, 7 bytes: offsets into MOVE_DELAY for Pac-Man by level (clamped to 6) */
extern const uint8_t *const PAC_DELAY_BASE;
/* ROM $BDC0, 7 bytes: offsets into MOVE_DELAY for the ghosts by level (clamped to 6) */
extern const uint8_t *const GHOST_DELAY_BASE;
/* ROM $BBF2, 6 bytes: ghost-house release timers: 3-byte windows picked by min(level, 3) */
extern const uint8_t *const HOUSE_RELEASE;
/* ROM $BBF8, 256 bytes: frames of solid frightened colour by level; the lookup is NOT clamped, past the 15 entries it reads the ROM bytes that follow */
extern const uint8_t *const FRIGHT_FRAMES;
/* RAM $0672, 256 bytes: phase at which the frightened period ends, by level; NOT clamped (20 entries, then the RAM that follows: start and patrol routes) */
extern const uint8_t *const FRIGHT_END;
/* ROM $BD26, 13 bytes: first glyph code of the bonus item by level (clamped to 12) */
extern const uint8_t *const BONUS_GLYPH;
/* RAM $0794, 26 bytes: 13 (thousands, hundreds) BCD digit pairs by level (clamped to 12) */
extern const uint8_t *const BONUS_SCORE;
/* ROM $BD6D, 13 bytes: offsets into BONUS_SCORE_GLYPHS by level (clamped to 12) */
extern const uint8_t *const BONUS_SCORE_GLYPH_OFFSETS;
/* ROM $BD45, 40 bytes: five screen codes each: the pop-up of the bonus score */
extern const uint8_t *const BONUS_SCORE_GLYPHS;
/* ROM $BB83, 10 bytes: y of the ten lattice rows */
extern const uint8_t *const JUNCTION_Y;
/* ROM $BB8D, 10 bytes: x of the ten lattice columns */
extern const uint8_t *const JUNCTION_X;
/* RAM $060E, 100 bytes: exit masks (1 up, 2 down, 4 left, 8 right), 10 rows of 10 columns */
extern const uint8_t *const JUNCTION_EXITS;
/* RAM $07C6, 9 bytes: mask of the exits a ghost may take, indexed by its direction (1, 2, 4, 8): the opposite one is removed */
extern const uint8_t *const NO_REVERSE;
/* RAM $07CF, 9 bytes: the opposite direction, indexed by direction */
extern const uint8_t *const REVERSE_DIR;

/* the whole images: the tables above are slices of them */
extern const uint8_t *const RAM_0600;
extern const uint8_t *const ROM_BA00;
extern const uint8_t *const MAZE_DATA;

/* install the three images (copied); 0 when the sizes are right, 1 when not (nothing is installed then) */
int tables_set(const uint8_t *ram_0600, size_t ram_n, const uint8_t *rom_ba00, size_t rom_n, const uint8_t *maze, size_t maze_n);
/* 1 once tables_set has succeeded */
int tables_ready(void);

/* one data table of the core: its name, where its bytes are, and the 6502 address they were read from */
typedef struct TableInfo {
    const char *name;
    const uint8_t *data;
    uint16_t count;
    uint16_t addr;   /* address in the 6502 memory the table was read from */
    uint8_t is_rom;  /* 1 = ROM, 0 = RAM expanded by Start */
} TableInfo;

#define PM_TABLE_COUNT 17
extern const TableInfo table_info[PM_TABLE_COUNT];

uint8_t table_ram(uint16_t addr);  /* a byte of RAM_0600 by its address ($0600-$07FF) */
uint8_t table_rom(uint16_t addr);  /* a byte of ROM_BA00 by its address ($BA00-$BFFF) */

#endif
